/* =========================================================
   MINI DASHBOARD CORE - Lesson 1 Capstone
   Combines: variables, console, statements, comments, logic
========================================================= */

// Config - const because fixed (like your dashboard)
const COURSE_ID = "javascript";
const TOTAL_LESSONS = 10;
const XP_PER_LESSON = 50;

// State - let because changes (like your dashboard)
let xp = 120;
let coins = 30;
let completed = 2;

// Function to calculate progress - like your updateProgress()
function calculateProgress(completed, total) {
  let percent = Math.round((completed / total) * 100);
  let text = `${completed} / ${total} completed`;
  return { percent, text };
}

// Function to get lesson status - like your createLessonCard logic
function getLessonStatus(lessonId, completed) {
  if (lessonId <= completed) return "completed";
  if (lessonId === completed + 1) return "current";
  return "locked";
}

// Simulate completing a lesson - like Start button click
function completeLesson(lessonId) {
  console.log(`\n--- Starting Lesson ${lessonId} ---`);

  let status = getLessonStatus(lessonId, completed);

  if (status === "locked") {
    console.warn(`Lesson ${lessonId} is locked! Complete lesson ${completed + 1} first.`);
    return;
  }

  if (status === "completed") {
    console.log(`Lesson ${lessonId} already completed - reviewing...`);
    return;
  }

  // Current lesson - complete it
  completed += 1;
  xp += XP_PER_LESSON;
  coins += 10;

  let progress = calculateProgress(completed, TOTAL_LESSONS);

  console.log(`✅ Lesson ${lessonId} completed!`);
  console.log(`💰 XP: ${xp} (+${XP_PER_LESSON}), Coins: ${coins} (+10)`);
  console.log(`📊 Progress: ${progress.text} - ${progress.percent}%`);
}

// Initial state
console.log("=== CODE ACADEMY DASHBOARD SIMULATION ===");
console.log(`Course: ${COURSE_ID}, Total Lessons: ${TOTAL_LESSONS}`);
let initialProgress = calculateProgress(completed, TOTAL_LESSONS);
console.log(`Initial: ${initialProgress.text} - ${initialProgress.percent}% - XP: ${xp}`);

